import { describe, it, expect } from 'vitest';
import fs from 'fs';
import path from 'path';

// The CS flow is Start -> city -> centre card, and the card is the end of the journey.
// Generated by userjourney/build_cs_support.js from "KB - List of Centres.json".
describe('CEO SUITE Customer Service & Support Flow Integrity', () => {
  const filePath = path.join(process.cwd(), 'userjourney', 'UserJourney-CS-Support.json');
  const flowData = JSON.parse(fs.readFileSync(filePath, 'utf8'));
  const intents: any[] = flowData.data.intents;
  const byName = new Map<string, any>(intents.map((i) => [i.name, i]));

  const kbPath = path.join(process.cwd(), 'userjourney', 'knowledge base', 'KB - List of Centres.json');
  const kb: any[] = JSON.parse(fs.readFileSync(kbPath, 'utf8'));

  // KB brand code -> centre name used in "Centre: <name>" (same names as src/lib/centres-directory.ts)
  const brandToCentre: Record<string, string> = {
    QU7: 'Axiata Tower', QSE: 'Q Sentral', MMX: 'Manara Maxis 36', MKL: 'Manara Maxis 26',
    WCC: 'Chinachem Tower', KHK: 'K11 Atelier Victoria Dockside', WNF: 'Nan Fung Tower',
    SUN: 'Sunshine Financial Center', LGT: 'The Exchange Twin Towers', LJZ: 'Lujiazui Finance Plaza',
    SWF: 'Shanghai World Financial Center', HKN: 'Hong Kong New World Tower (K11)', PAN: 'Ping An Finance Center',
    LKG: 'Lkg Tower', SSC: 'Sahid Sudirman Center', AXA: 'Axa Tower', IDX: 'Indonesia Stock Exchange Tower 2',
    OPP: 'One Pacific Place', CTN: 'Centennial Tower', SLT: 'Singapore Land Tower', KYB: 'Kyobo Building',
    PNS: 'Parnas Tower', ATT: 'Athenee Tower', LCH: 'Hanoi Lotte Center', VCB: 'Vietcombank Tower'
  };
  const brandToCity: Record<string, string> = {
    QU7: 'Kuala Lumpur', QSE: 'Kuala Lumpur', MMX: 'Kuala Lumpur', MKL: 'Kuala Lumpur',
    WCC: 'Hong Kong', KHK: 'Hong Kong', WNF: 'Hong Kong', SUN: 'Beijing', LGT: 'Beijing',
    LJZ: 'Shanghai', SWF: 'Shanghai', HKN: 'Shanghai', PAN: 'Hangzhou', LKG: 'Manila',
    SSC: 'Jakarta', AXA: 'Jakarta', IDX: 'Jakarta', OPP: 'Jakarta', CTN: 'Singapore', SLT: 'Singapore',
    KYB: 'Seoul', PNS: 'Seoul', ATT: 'Bangkok', LCH: 'Hanoi', VCB: 'Ho Chi Minh City'
  };
  const cities = Array.from(new Set(Object.values(brandToCity)));
  const START = 'Start / Main Menu';

  // Same matching as src/app/api/widget/message/route.ts: exact intent name or phrase, and - only when the
  // tenant's AI is off - the longest phrase contained in the message.
  function matchMessage(msg: string, aiEnabled = true) {
    const m = msg.toLowerCase().trim();
    let best: any = null;
    let bestLength = 0;
    for (const intent of intents) {
      if ((intent.name || '').toLowerCase().trim() === m) return intent;
      for (const phrase of intent.trainingPhrases || []) {
        const p = phrase.toLowerCase().trim();
        if (p === m) return intent;
        if (!aiEnabled && m.includes(p) && p.length > bestLength) {
          bestLength = p.length;
          best = intent;
        }
      }
    }
    return best;
  }
  const buttons = (intent: any): Array<[string, string]> =>
    intent?.options ? intent.options.split(', ').map((o: string) => o.split('|') as [string, string]) : [];

  it('TEST-CS-01 The flow has one start menu, one intent per city and one card per centre, nothing else', () => {
    expect(flowData.type).toBe('agent_flow');
    expect(flowData.data.name).toBe('CEO SUITE Customer Service & Support Flow');
    const centreCards = intents.filter((i) => i.name.startsWith('Centre: '));
    const cityLists = intents.filter((i) => i.name.startsWith('City Directory: '));
    expect(byName.has(START)).toBe(true);
    expect(cityLists.map((i) => i.name.replace('City Directory: ', '')).sort()).toEqual([...cities].sort());
    expect(centreCards.map((i) => i.name.replace('Centre: ', '')).sort()).toEqual(Object.values(brandToCentre).sort());
    expect(intents.length).toBe(1 + cities.length + Object.keys(brandToCentre).length);
    for (const card of centreCards) expect(card.responseType, card.name).toBe('card');
  });

  it('TEST-CS-02 Every button opens an intent of this flow', () => {
    const dangling: string[] = [];
    for (const intent of intents) {
      for (const [label, target] of buttons(intent)) {
        if (!byName.has(target)) dangling.push(`${intent.name}: "${label}" -> ${target}`);
      }
    }
    expect(dangling).toEqual([]);
  });

  it('TEST-CS-03 The journey is Start -> city -> centre card and ends there (no loops)', () => {
    expect(buttons(byName.get(START)).map(([, t]) => t).sort()).toEqual(cities.map((c) => `City Directory: ${c}`).sort());
    for (const city of cities) {
      const expected = Object.keys(brandToCity)
        .filter((b) => brandToCity[b] === city)
        .map((b) => `Centre: ${brandToCentre[b]}`);
      expect(buttons(byName.get(`City Directory: ${city}`)).map(([, t]) => t).sort(), city).toEqual(expected.sort());
    }
    for (const card of intents.filter((i) => i.name.startsWith('Centre: '))) {
      expect(card.options, `${card.name} must be the end of the journey`).toBe('');
    }
    // Every intent except Start is reached by exactly one button, so the flow is a tree
    const parents = new Map<string, number>();
    for (const intent of intents) for (const [, t] of buttons(intent)) parents.set(t, (parents.get(t) || 0) + 1);
    for (const intent of intents) {
      expect(parents.get(intent.name) ?? 0, intent.name).toBe(intent.name === START ? 0 : 1);
    }
  });

  it('TEST-CS-04 No "Start again", "Main Menu" or back buttons', () => {
    for (const intent of intents) {
      for (const [label, target] of buttons(intent)) {
        expect(label, intent.name).not.toMatch(/start again|main menu|back|other (cities|centres|centers)/i);
        expect(target, intent.name).not.toBe(START);
      }
    }
  });

  it('TEST-CS-04b Every intent is a fixed reply: the AI never rewrites the menu, city list or card', () => {
    // route.ts skips the LLM for metadata.fixedReply. Without it, a typed city ("saigon") was sent to the
    // AI, which replaced the city text with "I could not find that in my documents".
    for (const intent of intents) expect(intent.metadata?.fixedReply, intent.name).toBe(true);
  });

  it('TEST-CS-05 No duplicates: one intent per name, phrase and answer', () => {
    const seenNames = new Set<string>();
    const seenPhrases = new Map<string, string>();
    const seenResponses = new Map<string, string>();
    const failures: string[] = [];
    for (const intent of intents) {
      if (seenNames.has(intent.name)) failures.push(`name twice: ${intent.name}`);
      seenNames.add(intent.name);
      for (const p of intent.trainingPhrases) {
        const k = p.toLowerCase().replace(/\s+/g, ' ').trim();
        if (seenPhrases.has(k) && seenPhrases.get(k) !== intent.name) failures.push(`"${p}": ${seenPhrases.get(k)} / ${intent.name}`);
        seenPhrases.set(k, intent.name);
      }
      if (seenResponses.has(intent.response)) failures.push(`same answer: ${seenResponses.get(intent.response)} / ${intent.name}`);
      seenResponses.set(intent.response, intent.name);
    }
    expect(failures).toEqual([]);
  });

  it('TEST-CS-06 Greetings and "where are your centres" questions open the city list', () => {
    const failures: string[] = [];
    for (const q of ['hi', 'hello', 'halo', 'start', 'start again', 'menu', 'Main Menu', 'our centres', 'our center',
      'Our Centres & Locations', 'select our centre', 'find a center', 'locations', 'all centres', 'daftar lokasi', 'pilih lokasi', 'cabang ceo suite',
      'link lokasi', 'location link', 'google maps', 'email', 'alamat', 'address', 'nomor telepon',
      'jam buka', 'opening hours', 'jam operasional']) {
      const hit = matchMessage(q);
      if (hit?.name !== START) failures.push(`"${q}" -> ${hit?.name ?? 'no match'}`);
    }
    expect(failures).toEqual([]);
  });

  it('TEST-CS-07 Centre names, spelling variants and nicknames open that centre card', () => {
    const cases: Record<string, string> = {
      'Axa Tower': 'Axa Tower', 'AXA TOWER': 'Axa Tower', 'Sahid Sudirman Centre': 'Sahid Sudirman Center',
      'Menara Maxis 36': 'Manara Maxis 36', 'Manara Maxis 26': 'Manara Maxis 26',
      'Indonesia Stock Exchange': 'Indonesia Stock Exchange Tower 2', 'lotte center': 'Hanoi Lotte Center',
      'k11 atelier': 'K11 Atelier Victoria Dockside', 'Centre: Axa Tower': 'Axa Tower', 'Center: Axa Tower': 'Axa Tower'
    };
    for (const [q, centre] of Object.entries(cases)) expect(matchMessage(q)?.name, q).toBe(`Centre: ${centre}`);
  });

  it('TEST-CS-08 With the AI off, a sentence naming a centre or city still reaches it', () => {
    expect(matchMessage('i need the address of one pacific place', false)?.name).toBe('Centre: One Pacific Place');
    expect(matchMessage('where is the axa tower office please', false)?.name).toBe('Centre: Axa Tower');
    expect(matchMessage('do you have an office in hanoi?', false)?.name).toBe('City Directory: Hanoi');
  });

  describe('KB - List of Centres.json is the source of truth for centre details', () => {
    const to12h = (hhmm: string) => {
      const [h, m] = hhmm.split(':').map(Number);
      return `${h % 12 === 0 ? 12 : h % 12}:${String(m).padStart(2, '0')} ${h < 12 ? 'AM' : 'PM'}`;
    };
    const digits = (s: string) => s.replace(/\D/g, '');
    const plain = (html: string) => html.replace(/<[^>]*>/g, ' ');
    // Same cleaning rules as the card builder: markdown links reduced to text, HTML-escaped
    const clean = (t: string) => t.replace(/\[([^\]]*)\]\([^)]*\)/g, '$1').trim();
    const esc = (t: string) => t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const usable = (u: string) => /^https?:\/\//.test(u || '') && !/\.\.\.$/.test(u);

    it('TEST-CS-11 Every KB centre has a card in the flow', () => {
      expect(kb.map((c) => c.brand).filter((b) => !brandToCentre[b])).toEqual([]);
    });

    it('TEST-CS-12 Centre cards show the opening and closing hours from the KB', () => {
      const failures: string[] = [];
      for (const c of kb) {
        const centre = brandToCentre[c.brand];
        const expected = `${to12h(c.operating_hours.opening_time)} – ${to12h(c.operating_hours.closing_time)}`;
        if (!matchMessage(`Centre: ${centre}`)?.response.includes(expected)) failures.push(`${centre}: expected ${expected}`);
      }
      expect(failures).toEqual([]);
    });

    it('TEST-CS-13 Centre cards match the KB phone, address and website', () => {
      const failures: string[] = [];
      for (const c of kb) {
        const centre = brandToCentre[c.brand];
        const info = c.contact_information;
        const card = matchMessage(`Centre: ${centre}`);
        const text = plain(card?.response ?? '');
        if (!digits(text).includes(digits(info.phone))) failures.push(`${centre}: phone ${info.phone}`);
        // Address numbers (floor, street number, postcode) must all appear, in order
        const kbAddress = clean(info.address);
        if (!digits(text).includes(digits(kbAddress))) failures.push(`${centre}: address ${kbAddress}`);
        if (!(card?.response ?? '').includes(info.website)) failures.push(`${centre}: website ${info.website}`);
      }
      expect(failures).toEqual([]);
    });

    it('TEST-CS-16 Every KB field of every centre is in its card (address, map link, email, fax, convenience, amenities, description)', () => {
      const failures: string[] = [];
      for (const c of kb) {
        const centre = brandToCentre[c.brand];
        const ci = c.contact_information;
        const html: string = matchMessage(`Centre: ${centre}`)?.response ?? '';
        const must: string[] = [
          esc(clean(ci.address)),
          esc(ci.phone),
          ci.website,
          ...(ci.email ? [esc(ci.email)] : []),
          ...(ci.fax ? [esc(ci.fax)] : []),
          ...(usable(ci.location_url) ? [ci.location_url] : []),
          ...(c.convenience || []).map(esc),
          ...(c.amenities || []).map(esc),
          ...(c.description ? c.description.split('\n').filter(Boolean).map(esc) : [])
        ];
        for (const m of must) if (!html.includes(m)) failures.push(`${centre} missing "${m.slice(0, 60)}"`);
        // An empty or truncated KB link must not show up as a broken link
        if (!usable(ci.location_url) && html.includes('Location Map')) failures.push(`${centre} shows a broken map link`);
      }
      expect(failures).toEqual([]);
    });

    it('TEST-CS-17 Free-text questions about one centre (address, map link, email, hours, ...) reach that centre card', () => {
      const templates = ['address {n}', 'alamat {n}', 'link lokasi {n}', 'location link {n}', 'google maps {n}',
        'email {n}', 'phone {n}', 'jam buka {n}', 'jam tutup {n}', 'opening hours {n}', 'convenience {n}',
        'amenities {n}', 'fasilitas {n}', '{n} address', 'front desk {n}', 'resepsionis {n}'];
      const failures: string[] = [];
      for (const c of kb) {
        const centre = brandToCentre[c.brand];
        for (const n of [centre, c.brand]) {
          for (const t of templates) {
            const q = t.replace('{n}', n);
            const hit = matchMessage(q);
            if (hit?.name !== `Centre: ${centre}`) failures.push(`"${q}" -> ${hit?.name ?? 'no match'}`);
          }
        }
      }
      expect(failures).toEqual([]);
    });

    it('TEST-CS-18 City questions (centre jakarta, kantor di jakarta, ...) open that city\'s centre list', () => {
      const templates = ['{c}', 'centre {c}', 'center {c}', 'centre di {c}', 'kantor di {c}', 'office in {c}', 'lokasi {c}',
        'alamat {c}', 'link lokasi {c}', 'email {c}'];
      const failures: string[] = [];
      for (const city of cities) {
        for (const t of templates) {
          const q = t.replace('{c}', city);
          const hit = matchMessage(q);
          if (hit?.name !== `City Directory: ${city}`) failures.push(`"${q}" -> ${hit?.name ?? 'no match'}`);
        }
        // The city answer is short: the details are on the centre cards, not repeated here
        const dir = matchMessage(`City Directory: ${city}`);
        for (const c of kb.filter((k) => brandToCity[k.brand] === city)) {
          if (dir?.response.includes(esc(clean(c.contact_information.address)))) failures.push(`${city}: repeats an address`);
        }
      }
      expect(failures).toEqual([]);
    });

    it('TEST-CS-20 No WhatsApp numbers are shown for centres', () => {
      for (const i of intents) {
        expect(i.response ?? '', `${i.name} should not contain wa.me`).not.toContain('wa.me');
        expect(i.response ?? '', `${i.name} should not contain a WA number`).not.toMatch(/WA: \+/);
      }
    });
  });
});
